/* From Uiverse.io by forgingdestiny - Tags: simple, minimalist, loader, wave, css effect */
/* Container for the loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 10em;
}

/* Circle elements */
.__UIV_SCOPE__ .circle {
  width: 1em;
  height: 1em;
  margin: 0 0.25em;
  border-radius: 50%;
  background-color: #a8d5e2;
  animation: wave 1.5s infinite ease-in-out;
  transition: background-color 0.3s ease;
}

/* Animation */
@keyframes wave {
  0%, 100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-1em);
  }
}

/* Delay for each circle */
.__UIV_SCOPE__ .circle:nth-child(1) {
  animation-delay: 0s;
}

.__UIV_SCOPE__ .circle:nth-child(2) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .circle:nth-child(3) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .circle:nth-child(4) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .circle:nth-child(5) {
  animation-delay: 0.8s;
}
